PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE domains (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    url TEXT NOT NULL,
    active INTEGER DEFAULT 1,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE team (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    user_id TEXT NOT NULL UNIQUE,
    password TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, trafee_url TEXT);
CREATE TABLE links (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    slug TEXT NOT NULL UNIQUE,
    original_url TEXT NOT NULL,
    title TEXT,
    description TEXT,
    image_url TEXT,
    domain_id INTEGER REFERENCES domains(id),
    user_id TEXT,
    block_indonesia INTEGER DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
, url_trafee TEXT, routing_mode TEXT DEFAULT 'random');
CREATE TABLE settings (
    key TEXT PRIMARY KEY,
    value TEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE conversions (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  click_id TEXT NOT NULL,
  sub_id TEXT DEFAULT 'Unknown',
  network TEXT DEFAULT 'IMONETIZEIT',
  country TEXT DEFAULT 'US',
  country_name TEXT DEFAULT 'United States',
  traffic_type TEXT DEFAULT 'WEB',
  earning REAL DEFAULT 0.0,
  ip_address TEXT,
  user_agent TEXT,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, browser TEXT);
CREATE TABLE daily_reports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  date TEXT NOT NULL,
  smartlink TEXT NOT NULL,
  network TEXT DEFAULT 'IMONETIZEIT',
  visits INTEGER DEFAULT 0,
  unique_visits INTEGER DEFAULT 0,
  clicks INTEGER DEFAULT 0,
  leads INTEGER DEFAULT 0,
  payout REAL DEFAULT 0.0,
  epc REAL DEFAULT 0.0,
  cr REAL DEFAULT 0.0,
  updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
  UNIQUE(date, smartlink, network)
);
CREATE TABLE users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL UNIQUE,
  password TEXT NOT NULL,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);
CREATE TABLE clicks (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  slug TEXT,
  country TEXT DEFAULT 'XX',
  ip_address TEXT,
  click_id TEXT,
  os TEXT,
  browser TEXT,
  user_agent TEXT,
  referer TEXT,
  link_id INTEGER,
  created_at DATETIME DEFAULT CURRENT_TIMESTAMP
, s3 TEXT, user_id TEXT, network TEXT);
DELETE FROM sqlite_sequence;
CREATE INDEX idx_links_user_id ON links(user_id);
CREATE INDEX idx_links_slug ON links(slug);
